begin;

create schema if not exists ux;
grant usage on schema ux to authenticated;

create table if not exists ux.design_tokens(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null references core.organisations(id) on delete cascade,
 token_key text not null,category text not null,value jsonb not null,version int not null default 1 check(version>0),status text not null default 'draft' check(status in ('draft','review','published','retired')),
 supersedes_id uuid references ux.design_tokens(id) on delete set null,token_hash text not null,created_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organisation_id,token_key,version));
create table if not exists ux.ui_components(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null references core.organisations(id) on delete cascade,
 component_key text not null,name text not null,semantics jsonb not null default '{}'::jsonb,keyboard_contract jsonb not null default '{}'::jsonb,error_contract jsonb not null default '{}'::jsonb,responsive_contract jsonb not null default '{}'::jsonb,
 version int not null default 1 check(version>0),status text not null default 'draft' check(status in ('draft','review','published','retired')),supersedes_id uuid references ux.ui_components(id) on delete set null,component_hash text not null,created_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organisation_id,component_key,version));
create table if not exists ux.user_preferences(
 user_id uuid primary key references auth.users(id) on delete cascade,locale text not null default 'en-IN',unit_system text not null default 'metric',number_locale text not null default 'en-IN',currency_code text not null default 'INR',reduced_motion boolean not null default false,high_contrast boolean not null default false,density text not null default 'comfortable' check(density in ('comfortable','compact')),preferences jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists ux.saved_views(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,organisation_id uuid not null references core.organisations(id) on delete cascade,project_id uuid references project.projects(id) on delete cascade,name text not null,route text not null,filters jsonb not null default '{}'::jsonb,sort jsonb not null default '[]'::jsonb,layout jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,organisation_id,route,name));
create table if not exists ux.accessibility_audits(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null references core.organisations(id) on delete cascade,route text not null,commit_sha text not null,target_wcag text not null default '2.2 AA',automated_report_ref text,keyboard_evidence_ref text,screen_reader_evidence_ref text,status text not null default 'draft' check(status in ('draft','pass','fail')),created_by uuid not null references auth.users(id),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,notes text,audit_hash text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists ux.accessibility_findings(
 id uuid primary key default gen_random_uuid(),audit_id uuid not null references ux.accessibility_audits(id) on delete cascade,organisation_id uuid not null references core.organisations(id) on delete cascade,criterion text not null,severity text not null check(severity in ('low','medium','high','critical')),issue text not null,recovery_action text not null,status text not null default 'open' check(status in ('open','remediated','accepted')),evidence_ref text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists ux.localisation_entries(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null references core.organisations(id) on delete cascade,locale text not null,entry_key text not null,entry_value text not null,status text not null default 'draft' check(status in ('draft','published','retired')),version int not null default 1 check(version>0),created_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(organisation_id,locale,entry_key,version));
create table if not exists ux.glossary_terms(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null references core.organisations(id) on delete cascade,locale text not null default 'en-IN',term text not null,definition text not null,status text not null default 'draft' check(status in ('draft','published','retired')),version int not null default 1 check(version>0),created_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(organisation_id,locale,term,version));
create table if not exists ux.help_guides(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null references core.organisations(id) on delete cascade,guide_key text not null,title text not null,route text,content_ref text not null,status text not null default 'draft' check(status in ('draft','published','retired')),version int not null default 1 check(version>0),created_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(organisation_id,guide_key,version));

alter table ux.design_tokens enable row level security;alter table ux.ui_components enable row level security;alter table ux.user_preferences enable row level security;alter table ux.saved_views enable row level security;alter table ux.accessibility_audits enable row level security;alter table ux.accessibility_findings enable row level security;alter table ux.localisation_entries enable row level security;alter table ux.glossary_terms enable row level security;alter table ux.help_guides enable row level security;
grant select,insert,update on ux.design_tokens,ux.ui_components,ux.accessibility_audits,ux.accessibility_findings,ux.localisation_entries,ux.glossary_terms,ux.help_guides to authenticated;
grant select,insert,update,delete on ux.user_preferences,ux.saved_views to authenticated;

do $$ declare t text;begin foreach t in array array['design_tokens','ui_components','accessibility_audits','accessibility_findings','localisation_entries','glossary_terms','help_guides'] loop execute format('create policy %I on ux.%I for select to authenticated using (core.is_platform_admin())','ux_admin_read_'||t,t);end loop;end $$;
create policy ux_pref_self_read on ux.user_preferences for select to authenticated using(user_id=auth.uid());create policy ux_pref_self_insert on ux.user_preferences for insert to authenticated with check(user_id=auth.uid());create policy ux_pref_self_update on ux.user_preferences for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy ux_view_self_read on ux.saved_views for select to authenticated using(user_id=auth.uid() and core.is_org_member(organisation_id));create policy ux_view_self_insert on ux.saved_views for insert to authenticated with check(user_id=auth.uid() and core.is_org_member(organisation_id) and (project_id is null or project.can_access_project(project_id)));create policy ux_view_self_update on ux.saved_views for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and core.is_org_member(organisation_id) and (project_id is null or project.can_access_project(project_id)));create policy ux_view_self_delete on ux.saved_views for delete to authenticated using(user_id=auth.uid());
create policy ux_token_insert on ux.design_tokens for insert to authenticated with check(core.is_platform_admin() and created_by=auth.uid() and current_setting('conceptspaces.ux_phase',true)='draft');create policy ux_token_update on ux.design_tokens for update to authenticated using(core.is_platform_admin()) with check(core.is_platform_admin() and current_setting('conceptspaces.ux_phase',true) in ('review','publish','retire'));
create policy ux_component_insert on ux.ui_components for insert to authenticated with check(core.is_platform_admin() and created_by=auth.uid() and current_setting('conceptspaces.ux_phase',true)='draft');create policy ux_component_update on ux.ui_components for update to authenticated using(core.is_platform_admin()) with check(core.is_platform_admin() and current_setting('conceptspaces.ux_phase',true) in ('review','publish','retire'));
create policy ux_audit_insert on ux.accessibility_audits for insert to authenticated with check(core.is_platform_admin() and created_by=auth.uid() and current_setting('conceptspaces.ux_phase',true)='audit_create');create policy ux_audit_update on ux.accessibility_audits for update to authenticated using(core.is_platform_admin()) with check(core.is_platform_admin() and current_setting('conceptspaces.ux_phase',true)='audit_review');
create policy ux_finding_insert on ux.accessibility_findings for insert to authenticated with check(core.is_platform_admin() and created_by=auth.uid() and current_setting('conceptspaces.ux_phase',true)='finding');create policy ux_finding_update on ux.accessibility_findings for update to authenticated using(core.is_platform_admin()) with check(core.is_platform_admin() and current_setting('conceptspaces.ux_phase',true)='finding');
do $$ declare t text;begin foreach t in array array['localisation_entries','glossary_terms','help_guides'] loop execute format('create policy %I on ux.%I for insert to authenticated with check (core.is_platform_admin() and created_by=auth.uid() and current_setting(''conceptspaces.ux_phase'',true)=''registry'')','ux_registry_insert_'||t,t);execute format('create policy %I on ux.%I for update to authenticated using (core.is_platform_admin()) with check (core.is_platform_admin() and current_setting(''conceptspaces.ux_phase'',true)=''registry'')','ux_registry_update_'||t,t);end loop;end $$;

create or replace function public.upsert_user_preferences(input_payload jsonb) returns jsonb language plpgsql security invoker set search_path='ux','auth','pg_temp' as $$declare r ux.user_preferences%rowtype;begin if auth.uid() is null then raise exception 'authentication_required';end if;insert into ux.user_preferences(user_id,locale,unit_system,number_locale,currency_code,reduced_motion,high_contrast,density,preferences) values(auth.uid(),coalesce(nullif(btrim(input_payload->>'locale'),''),'en-IN'),coalesce(nullif(btrim(input_payload->>'unit_system'),''),'metric'),coalesce(nullif(btrim(input_payload->>'number_locale'),''),'en-IN'),coalesce(nullif(btrim(input_payload->>'currency_code'),''),'INR'),coalesce((input_payload->>'reduced_motion')::boolean,false),coalesce((input_payload->>'high_contrast')::boolean,false),coalesce(nullif(btrim(input_payload->>'density'),''),'comfortable'),coalesce(input_payload->'preferences','{}'::jsonb)) on conflict(user_id) do update set locale=excluded.locale,unit_system=excluded.unit_system,number_locale=excluded.number_locale,currency_code=excluded.currency_code,reduced_motion=excluded.reduced_motion,high_contrast=excluded.high_contrast,density=excluded.density,preferences=excluded.preferences,updated_at=now() returning * into r;return to_jsonb(r);end;$$;revoke all on function public.upsert_user_preferences(jsonb) from public,anon;grant execute on function public.upsert_user_preferences(jsonb) to authenticated;
create or replace function public.save_user_view(target_organisation_id uuid,target_project_id uuid,input_payload jsonb) returns uuid language plpgsql security invoker set search_path='ux','core','project','auth','pg_temp' as $$declare r ux.saved_views%rowtype;begin if auth.uid() is null or not core.is_org_member(target_organisation_id) or (target_project_id is not null and not project.can_access_project(target_project_id)) then raise exception 'saved_view_scope_denied';end if;if nullif(btrim(input_payload->>'name'),'') is null or nullif(btrim(input_payload->>'route'),'') is null then raise exception 'saved_view_name_and_route_required';end if;insert into ux.saved_views(user_id,organisation_id,project_id,name,route,filters,sort,layout) values(auth.uid(),target_organisation_id,target_project_id,btrim(input_payload->>'name'),btrim(input_payload->>'route'),coalesce(input_payload->'filters','{}'::jsonb),coalesce(input_payload->'sort','[]'::jsonb),coalesce(input_payload->'layout','{}'::jsonb)) on conflict(user_id,organisation_id,route,name) do update set project_id=excluded.project_id,filters=excluded.filters,sort=excluded.sort,layout=excluded.layout,updated_at=now() returning * into r;return r.id;end;$$;revoke all on function public.save_user_view(uuid,uuid,jsonb) from public,anon;grant execute on function public.save_user_view(uuid,uuid,jsonb) to authenticated;

create or replace function public.create_design_token(target_organisation_id uuid,input_payload jsonb) returns uuid language plpgsql security invoker set search_path='ux','core','audit','extensions','auth','pg_temp' as $$declare prior ux.design_tokens%rowtype;r ux.design_tokens%rowtype;v int;h text;begin if auth.uid() is null or not core.is_platform_admin() or not core.is_org_member(target_organisation_id) then raise exception 'ux_admin_authority_required';end if;if nullif(btrim(input_payload->>'token_key'),'') is null or nullif(btrim(input_payload->>'category'),'') is null or input_payload->'value' is null then raise exception 'design_token_fields_required';end if;select * into prior from ux.design_tokens where organisation_id=target_organisation_id and token_key=btrim(input_payload->>'token_key') and status='published' order by version desc limit 1;v:=coalesce(prior.version,0)+1;h:=encode(extensions.digest(jsonb_build_object('organisation_id',target_organisation_id,'key',btrim(input_payload->>'token_key'),'category',btrim(input_payload->>'category'),'value',input_payload->'value','version',v,'supersedes',prior.id)::text,'sha256'),'hex');perform set_config('conceptspaces.ux_phase','draft',true);insert into ux.design_tokens(organisation_id,token_key,category,value,version,supersedes_id,token_hash,created_by) values(target_organisation_id,btrim(input_payload->>'token_key'),btrim(input_payload->>'category'),input_payload->'value',v,prior.id,h,auth.uid()) returning * into r;perform audit.append_event(target_organisation_id,null,'ui.design_token_drafted','design_token',r.id,null,to_jsonb(r),h,gen_random_uuid());return r.id;end;$$;revoke all on function public.create_design_token(uuid,jsonb) from public,anon;grant execute on function public.create_design_token(uuid,jsonb) to authenticated;
create or replace function public.transition_design_token(target_id uuid,target_status text,target_reason text) returns text language plpgsql security invoker set search_path='ux','core','audit','auth','pg_temp' as $$declare r ux.design_tokens%rowtype;s text:=lower(btrim(target_status));before_state jsonb;begin select * into r from ux.design_tokens where id=target_id for update;if not found then raise exception 'design_token_not_found';end if;if auth.uid() is null or not core.is_platform_admin() or nullif(btrim(target_reason),'') is null then raise exception 'ux_admin_authority_and_reason_required';end if;if (r.status='draft' and s<>'review') or (r.status='review' and s not in ('draft','published')) or (r.status='published' and s<>'retired') then raise exception 'design_token_transition_invalid';end if;if s='published' and r.created_by=auth.uid() then raise exception 'maker_cannot_publish_own_design_token';end if;before_state:=to_jsonb(r);perform set_config('conceptspaces.ux_phase',case when s='published' then 'publish' when s='retired' then 'retire' else 'review' end,true);update ux.design_tokens set status=s,approved_by=case when s='published' then auth.uid() else approved_by end,approved_at=case when s='published' then now() else approved_at end,updated_at=now() where id=r.id returning * into r;if s='published' and r.supersedes_id is not null then perform set_config('conceptspaces.ux_phase','retire',true);update ux.design_tokens set status='retired',updated_at=now() where id=r.supersedes_id and status='published';end if;perform audit.append_event(r.organisation_id,null,'ui.design_token_'||s,'design_token',r.id,before_state,to_jsonb(r),target_reason,gen_random_uuid());return r.status;end;$$;revoke all on function public.transition_design_token(uuid,text,text) from public,anon;grant execute on function public.transition_design_token(uuid,text,text) to authenticated;

create or replace function public.create_ui_component_contract(target_organisation_id uuid,input_payload jsonb) returns uuid language plpgsql security invoker set search_path='ux','core','audit','extensions','auth','pg_temp' as $$declare prior ux.ui_components%rowtype;r ux.ui_components%rowtype;v int;h text;begin if auth.uid() is null or not core.is_platform_admin() or not core.is_org_member(target_organisation_id) then raise exception 'ux_admin_authority_required';end if;if nullif(btrim(input_payload->>'component_key'),'') is null or nullif(btrim(input_payload->>'name'),'') is null then raise exception 'ui_component_fields_required';end if;select * into prior from ux.ui_components where organisation_id=target_organisation_id and component_key=btrim(input_payload->>'component_key') and status='published' order by version desc limit 1;v:=coalesce(prior.version,0)+1;h:=encode(extensions.digest(jsonb_build_object('organisation_id',target_organisation_id,'key',btrim(input_payload->>'component_key'),'name',btrim(input_payload->>'name'),'semantics',coalesce(input_payload->'semantics','{}'::jsonb),'keyboard',coalesce(input_payload->'keyboard_contract','{}'::jsonb),'errors',coalesce(input_payload->'error_contract','{}'::jsonb),'responsive',coalesce(input_payload->'responsive_contract','{}'::jsonb),'version',v)::text,'sha256'),'hex');perform set_config('conceptspaces.ux_phase','draft',true);insert into ux.ui_components(organisation_id,component_key,name,semantics,keyboard_contract,error_contract,responsive_contract,version,supersedes_id,component_hash,created_by) values(target_organisation_id,btrim(input_payload->>'component_key'),btrim(input_payload->>'name'),coalesce(input_payload->'semantics','{}'::jsonb),coalesce(input_payload->'keyboard_contract','{}'::jsonb),coalesce(input_payload->'error_contract','{}'::jsonb),coalesce(input_payload->'responsive_contract','{}'::jsonb),v,prior.id,h,auth.uid()) returning * into r;perform audit.append_event(target_organisation_id,null,'ui.component_drafted','ui_component',r.id,null,to_jsonb(r),h,gen_random_uuid());return r.id;end;$$;revoke all on function public.create_ui_component_contract(uuid,jsonb) from public,anon;grant execute on function public.create_ui_component_contract(uuid,jsonb) to authenticated;
create or replace function public.transition_ui_component_contract(target_id uuid,target_status text,target_reason text) returns text language plpgsql security invoker set search_path='ux','core','audit','auth','pg_temp' as $$declare r ux.ui_components%rowtype;s text:=lower(btrim(target_status));before_state jsonb;begin select * into r from ux.ui_components where id=target_id for update;if not found then raise exception 'ui_component_not_found';end if;if auth.uid() is null or not core.is_platform_admin() or nullif(btrim(target_reason),'') is null then raise exception 'ux_admin_authority_and_reason_required';end if;if (r.status='draft' and s<>'review') or (r.status='review' and s not in ('draft','published')) or (r.status='published' and s<>'retired') then raise exception 'ui_component_transition_invalid';end if;if s='published' and r.created_by=auth.uid() then raise exception 'maker_cannot_publish_own_ui_component';end if;before_state:=to_jsonb(r);perform set_config('conceptspaces.ux_phase',case when s='published' then 'publish' when s='retired' then 'retire' else 'review' end,true);update ux.ui_components set status=s,approved_by=case when s='published' then auth.uid() else approved_by end,approved_at=case when s='published' then now() else approved_at end,updated_at=now() where id=r.id returning * into r;if s='published' and r.supersedes_id is not null then perform set_config('conceptspaces.ux_phase','retire',true);update ux.ui_components set status='retired',updated_at=now() where id=r.supersedes_id and status='published';end if;perform audit.append_event(r.organisation_id,null,'ui.component_'||s,'ui_component',r.id,before_state,to_jsonb(r),target_reason,gen_random_uuid());return r.status;end;$$;revoke all on function public.transition_ui_component_contract(uuid,text,text) from public,anon;grant execute on function public.transition_ui_component_contract(uuid,text,text) to authenticated;

create or replace function public.create_accessibility_audit(target_organisation_id uuid,input_payload jsonb) returns uuid language plpgsql security invoker set search_path='ux','core','audit','extensions','auth','pg_temp' as $$declare r ux.accessibility_audits%rowtype;h text;begin if auth.uid() is null or not core.is_platform_admin() or not core.is_org_member(target_organisation_id) then raise exception 'accessibility_audit_authority_required';end if;if nullif(btrim(input_payload->>'route'),'') is null or nullif(btrim(input_payload->>'commit_sha'),'') is null then raise exception 'accessibility_route_and_commit_required';end if;h:=encode(extensions.digest(jsonb_build_object('organisation_id',target_organisation_id,'route',btrim(input_payload->>'route'),'commit_sha',btrim(input_payload->>'commit_sha'),'target_wcag',coalesce(nullif(btrim(input_payload->>'target_wcag'),''),'2.2 AA'),'automated_report_ref',input_payload->>'automated_report_ref')::text,'sha256'),'hex');perform set_config('conceptspaces.ux_phase','audit_create',true);insert into ux.accessibility_audits(organisation_id,route,commit_sha,target_wcag,automated_report_ref,created_by,audit_hash) values(target_organisation_id,btrim(input_payload->>'route'),btrim(input_payload->>'commit_sha'),coalesce(nullif(btrim(input_payload->>'target_wcag'),''),'2.2 AA'),nullif(btrim(input_payload->>'automated_report_ref'),''),auth.uid(),h) returning * into r;perform audit.append_event(target_organisation_id,null,'ui.accessibility_audit_created','accessibility_audit',r.id,null,to_jsonb(r),h,gen_random_uuid());return r.id;end;$$;revoke all on function public.create_accessibility_audit(uuid,jsonb) from public,anon;grant execute on function public.create_accessibility_audit(uuid,jsonb) to authenticated;
create or replace function public.record_accessibility_finding(target_audit_id uuid,input_payload jsonb) returns uuid language plpgsql security invoker set search_path='ux','core','audit','auth','pg_temp' as $$declare a ux.accessibility_audits%rowtype;r ux.accessibility_findings%rowtype;sev text:=lower(btrim(input_payload->>'severity'));begin select * into a from ux.accessibility_audits where id=target_audit_id;if not found or auth.uid() is null or not core.is_platform_admin() then raise exception 'accessibility_audit_authority_required';end if;if sev not in ('low','medium','high','critical') or nullif(btrim(input_payload->>'criterion'),'') is null or nullif(btrim(input_payload->>'issue'),'') is null or nullif(btrim(input_payload->>'recovery_action'),'') is null then raise exception 'accessibility_finding_fields_invalid';end if;perform set_config('conceptspaces.ux_phase','finding',true);insert into ux.accessibility_findings(audit_id,organisation_id,criterion,severity,issue,recovery_action,evidence_ref,created_by) values(a.id,a.organisation_id,btrim(input_payload->>'criterion'),sev,btrim(input_payload->>'issue'),btrim(input_payload->>'recovery_action'),nullif(btrim(input_payload->>'evidence_ref'),''),auth.uid()) returning * into r;perform audit.append_event(a.organisation_id,null,'ui.accessibility_violation_detected','accessibility_finding',r.id,null,to_jsonb(r),null,gen_random_uuid());return r.id;end;$$;revoke all on function public.record_accessibility_finding(uuid,jsonb) from public,anon;grant execute on function public.record_accessibility_finding(uuid,jsonb) to authenticated;
create or replace function public.complete_accessibility_audit(target_audit_id uuid,input_payload jsonb) returns text language plpgsql security invoker set search_path='ux','core','audit','extensions','auth','pg_temp' as $$declare a ux.accessibility_audits%rowtype;before_state jsonb;decision text:=lower(btrim(input_payload->>'status'));h text;begin select * into a from ux.accessibility_audits where id=target_audit_id for update;if not found or auth.uid() is null or not core.is_platform_admin() then raise exception 'accessibility_audit_authority_required';end if;if a.created_by=auth.uid() then raise exception 'independent_accessibility_review_required';end if;if decision not in ('pass','fail') or nullif(btrim(input_payload->>'reason'),'') is null then raise exception 'accessibility_audit_decision_invalid';end if;if decision='pass' and (nullif(btrim(input_payload->>'automated_report_ref'),'') is null or nullif(btrim(input_payload->>'keyboard_evidence_ref'),'') is null or nullif(btrim(input_payload->>'screen_reader_evidence_ref'),'') is null) then raise exception 'ACCESSIBILITY_EVIDENCE_INCOMPLETE';end if;if decision='pass' and exists(select 1 from ux.accessibility_findings f where f.audit_id=a.id and f.status='open' and f.severity in ('high','critical')) then raise exception 'ACCESSIBILITY_HIGH_CRITICAL_FINDINGS_OPEN';end if;before_state:=to_jsonb(a);h:=encode(extensions.digest(jsonb_build_object('audit_hash',a.audit_hash,'status',decision,'automated',input_payload->>'automated_report_ref','keyboard',input_payload->>'keyboard_evidence_ref','screen_reader',input_payload->>'screen_reader_evidence_ref','reason',btrim(input_payload->>'reason'))::text,'sha256'),'hex');perform set_config('conceptspaces.ux_phase','audit_review',true);update ux.accessibility_audits set status=decision,automated_report_ref=nullif(btrim(input_payload->>'automated_report_ref'),''),keyboard_evidence_ref=nullif(btrim(input_payload->>'keyboard_evidence_ref'),''),screen_reader_evidence_ref=nullif(btrim(input_payload->>'screen_reader_evidence_ref'),''),reviewed_by=auth.uid(),reviewed_at=now(),notes=btrim(input_payload->>'reason'),audit_hash=h,updated_at=now() where id=a.id returning * into a;perform audit.append_event(a.organisation_id,null,case when decision='pass' then 'ui.accessibility_audit_passed' else 'ui.accessibility_audit_failed' end,'accessibility_audit',a.id,before_state,to_jsonb(a),input_payload->>'reason',gen_random_uuid());return a.status;end;$$;revoke all on function public.complete_accessibility_audit(uuid,jsonb) from public,anon;grant execute on function public.complete_accessibility_audit(uuid,jsonb) to authenticated;

create or replace function public.create_ux_registry_entry(target_organisation_id uuid,target_kind text,input_payload jsonb) returns uuid language plpgsql security invoker set search_path='ux','core','audit','auth','pg_temp' as $$declare k text:=lower(btrim(target_kind));rid uuid;begin if auth.uid() is null or not core.is_platform_admin() or not core.is_org_member(target_organisation_id) then raise exception 'ux_admin_authority_required';end if;perform set_config('conceptspaces.ux_phase','registry',true);if k='localisation' then insert into ux.localisation_entries(organisation_id,locale,entry_key,entry_value,created_by) values(target_organisation_id,coalesce(nullif(btrim(input_payload->>'locale'),''),'en-IN'),btrim(input_payload->>'key'),btrim(input_payload->>'value'),auth.uid()) returning id into rid;elsif k='glossary' then insert into ux.glossary_terms(organisation_id,locale,term,definition,created_by) values(target_organisation_id,coalesce(nullif(btrim(input_payload->>'locale'),''),'en-IN'),btrim(input_payload->>'term'),btrim(input_payload->>'definition'),auth.uid()) returning id into rid;elsif k='help' then insert into ux.help_guides(organisation_id,guide_key,title,route,content_ref,created_by) values(target_organisation_id,btrim(input_payload->>'guide_key'),btrim(input_payload->>'title'),nullif(btrim(input_payload->>'route'),''),btrim(input_payload->>'content_ref'),auth.uid()) returning id into rid;else raise exception 'ux_registry_kind_invalid';end if;perform audit.append_event(target_organisation_id,null,'ui.registry_entry_created',k,rid,null,input_payload,null,gen_random_uuid());return rid;end;$$;revoke all on function public.create_ux_registry_entry(uuid,text,jsonb) from public,anon;grant execute on function public.create_ux_registry_entry(uuid,text,jsonb) to authenticated;

create or replace function public.list_design_system_workspace(target_organisation_id uuid) returns jsonb language plpgsql stable security invoker set search_path='ux','core','auth','pg_temp' as $$begin if auth.uid() is null or not core.is_org_member(target_organisation_id) then raise exception 'organisation_access_required';end if;return jsonb_build_object('tokens',case when core.is_platform_admin() then coalesce((select jsonb_agg(to_jsonb(t) order by t.token_key,t.version desc) from ux.design_tokens t where t.organisation_id=target_organisation_id),'[]'::jsonb) else '[]'::jsonb end,'components',case when core.is_platform_admin() then coalesce((select jsonb_agg(to_jsonb(c) order by c.component_key,c.version desc) from ux.ui_components c where c.organisation_id=target_organisation_id),'[]'::jsonb) else '[]'::jsonb end,'preferences',coalesce((select to_jsonb(p) from ux.user_preferences p where p.user_id=auth.uid()),'{}'::jsonb),'saved_views',coalesce((select jsonb_agg(to_jsonb(v) order by v.updated_at desc) from ux.saved_views v where v.user_id=auth.uid() and v.organisation_id=target_organisation_id),'[]'::jsonb),'audits',case when core.is_platform_admin() then coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from ux.accessibility_audits a where a.organisation_id=target_organisation_id),'[]'::jsonb) else '[]'::jsonb end,'findings',case when core.is_platform_admin() then coalesce((select jsonb_agg(to_jsonb(f) order by f.created_at desc) from ux.accessibility_findings f where f.organisation_id=target_organisation_id),'[]'::jsonb) else '[]'::jsonb end,'localisation',case when core.is_platform_admin() then coalesce((select jsonb_agg(to_jsonb(l) order by l.locale,l.entry_key,l.version desc) from ux.localisation_entries l where l.organisation_id=target_organisation_id),'[]'::jsonb) else '[]'::jsonb end,'glossary',case when core.is_platform_admin() then coalesce((select jsonb_agg(to_jsonb(g) order by g.term,g.version desc) from ux.glossary_terms g where g.organisation_id=target_organisation_id),'[]'::jsonb) else '[]'::jsonb end,'help_guides',case when core.is_platform_admin() then coalesce((select jsonb_agg(to_jsonb(h) order by h.guide_key,h.version desc) from ux.help_guides h where h.organisation_id=target_organisation_id),'[]'::jsonb) else '[]'::jsonb end);end;$$;revoke all on function public.list_design_system_workspace(uuid) from public,anon;grant execute on function public.list_design_system_workspace(uuid) to authenticated;

commit;
